importAppearancePresetEnvelope.source:
function importAppearancePresetEnvelope(presetLike) {
    const presetApi = window.VibeMolPreset;
    if (!presetApi || typeof presetApi.import !== 'function') return null;
    return runWithAppearancePresetAutosaveSuppressed(() => (
      presetApi.import(buildAppearanceAutosaveImportEnvelope(presetLike), { mode: PRESET_MODE.RELAXED })
    ));
  }

restoreAppearancePresetAutosave.source:
function restoreAppearancePresetAutosave() {
    if (appearanceStudy) return false;
    try {
      const raw = window.localStorage.getItem(AUTOSAVE_STORAGE_KEY);
      if (!raw) return false;
      const parsed = JSON.parse(raw);
      importAppearancePresetEnvelope(parsed);
      syncAppearancePersistenceUi();
      console.info('VibeMol: restored autosaved appearance preset');
      return true;
    } catch (err) {
      console.warn('VibeMol: autosave restore failed', err);
      return false;
    }
  }

updateSidePanel.source:
function updateSidePanel() {
    syncEditSceneTool();
    measurementsPanel?.sync();
    syncCalculations();
    const record = currentIndex >= 0 ? volumes[currentIndex] : null;
    ensureListPopovers();
    if (coordsListPopover) coordsListPopover.cancelInlineEdit({ focusButton: false });
    coordsInlineEditState = null;
    setCoordsHoveredAtomIndex(-1);
    syncCoordsUnitsUi();
    renderCoordsPanelIfOpen();
    updatePubChemMetadataPanel(record);
    syncMoldenOrbitalsPanel(record);
    syncTrajectoryControls();
    syncVibrationControls();
    updateAutoIsoButtonState();
    updateEditAdaptiveMenuUi();
  }

updatePubChemMetadataPanel.source:
function updatePubChemMetadataPanel(record) {
    if (!pubchemMetaContent) return;
    const meta = record && record.pubchemMeta;
    if (!meta) {
      if (pubchemMetaWrap) pubchemMetaWrap.style.display = 'none';
      pubchemMetaContent.innerHTML = '';
      return;
    }
    if (pubchemMetaWrap) pubchemMetaWrap.style.display = 'block';
    const rows = [
      ['Name', meta.title || '—'],
      ['CID', meta.cid != null ? String(meta.cid) : '—'],
      ['Formula', meta.molecularFormula || '—'],
      ['Molar mass', meta.molecularWeight ? `${meta.molecularWeight} g/mol` : '—'],
      ['IUPAC', meta.iupacName || '—'],
      ['SMILES', meta.connectivitySmiles || '—'],
      ['Source', meta.source || 'PubChem']
    ];
    if (meta.query) rows.splice(1, 0, ['Query', meta.query]);
    if (meta.url) rows.push(['URL', meta.url]);
    const body = rows.map(([k, v]) => {
      return `<tr><th>${escapeHtml(k)}</th><td>${escapeHtml(v)}</td></tr>`;
    }).join('');
    pubchemMetaContent.innerHTML = `<table class="meta-table pubchem-metadata"><tbody>${body}</tbody></table>`;
  }

